test('adding tasks preserves an existing Task 001 project database', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-migration-'));
  const path = join(directory, 'existing.sqlite');
  let store;
  try {
    const previousDatabase = new DatabaseSync(path);
    try {
      previousDatabase.exec(`
        CREATE TABLE projects (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          name TEXT NOT NULL CHECK (length(trim(name)) > 0)
        );
        INSERT INTO projects (id, name) VALUES (42, 'Existing project');
      `);
    } finally {
      previousDatabase.close();
    }
    store = openProjects(path);
    assert.deepEqual(store.list(), [{ id: 42, name: 'Existing project', archived: false, total_count: 0, completed_count: 0 }]);
    assert.deepEqual(store.tasks.list(42), []);
    const task = store.tasks.create(42, '  Existing project task  ');
    assert.equal(task.title, 'Existing project task');
    assert.equal(task.completed, false);
    assert.throws(() => store.tasks.create(999, 'Orphan'), /FOREIGN KEY/);
    assert.throws(() => store.tasks.create(42, ' \t\n '), /Task title is required/);
    assert.deepEqual(store.tasks.list(42), [task]);
    store.tasks.setCompleted(42, task.id, true);
    assert.equal(store.get(42).completed_count, 1);
    assert.equal(store.get(42).total_count, 1);
    store.setArchived(42, true);
    store.close();
    store = openProjects(path);
    assert.equal(store.get(42).archived, true);
    assert.deepEqual(store.tasks.list(42), [{ ...task, completed: true }]);
    store.setArchived(42, false);
    assert.equal(store.get(42).completed_count, 1);
    assert.ok(store.create('Next project').id > 42);
  } finally {
    store?.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test('archive migration preserves existing Task 002 tasks and completion counts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-task-migration-'));
  const path = join(directory, 'existing.sqlite');
  let store;
  try {
    const previousDatabase = new DatabaseSync(path);
    try {
      previousDatabase.exec(`
        CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
        INSERT INTO projects (id, name) VALUES (7, 'Existing tasks');
      `);
      const tasks = createTaskStore(previousDatabase);
      const completed = tasks.create(7, 'Completed task');
      tasks.setCompleted(7, completed.id, true);
      tasks.create(7, 'Open task');
    } finally {
      previousDatabase.close();
    }
    store = openProjects(path);
    assert.deepEqual(store.get(7), {
      id: 7, name: 'Existing tasks', archived: false, total_count: 2, completed_count: 1,
    });
    assert.deepEqual(store.tasks.list(7).map((task) => task.completed), [true, false]);
    store.setArchived(7, true);
    store.close();
    store = openProjects(path);
    assert.equal(store.get(7).archived, true);
    assert.equal(store.get(7).completed_count, 1);
    assert.deepEqual(store.tasks.list(7).map((task) => task.title), ['Completed task', 'Open task']);
  } finally {
    store?.close();
    await rm(directory, { recursive: true, force: true });
  }
});
# Workboard

Requires Node.js 22.22.1. No package installation is needed.

```sh
npm start
```

The server binds to `0.0.0.0` on `PORT` (default `8080`). Set `DB_PATH` to the SQLite file to use (default `./data/workboard.sqlite`). Its parent directory is created automatically. Keep this file across server restarts to preserve projects, tasks, completion state, and archive state. Existing databases are migrated automatically.

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
npm test
```

`GET /health` returns `{"status":"ok"}`. The browser provides project creation at `/` and individual project pages at `/projects/<id>`.

Project pages support task creation, saved completion checkboxes, and All/Open/Completed filters. Tasks belong only to their project; filters default to All on each page load.

The project list defaults to Active and can show Archived projects. Archive and restore preserve all tasks. Archived project pages allow viewing and filtering tasks while task creation and completion controls are disabled; the server also rejects these changes. Each project row shows completed/total counts across all its tasks.

Active project pages allow renaming with a trimmed, nonempty name. Names persist without changing project URLs, list order, tasks, or summaries. Archived projects cannot be renamed until restored; both the browser controls and server enforce this restriction.

Each task row allows renaming with a trimmed, nonempty title. Renaming preserves ownership, creation order, completion state, filter membership, and project summaries. The completion checkbox label follows the saved title. Archived projects disable task rename controls and reject title updates until restored. Task titles persist across reloads and server restarts.
